// EmployeeDashboard.jsx - Fixed for API status casing
import React, { useEffect, useState } from 'react';
import { Link } from 'react-router-dom';
import api from "../api/axios";

const EmployeeDashboard = () => {
  const token = useSelector((state) => state.auth.token);
  const user = useSelector((state) => state.auth.user);

  const [tickets, setTickets] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    if (!user || !token) {
      setError('Please log in to view your tickets.');
      setLoading(false);
      return;
    }

    const fetchTickets = async () => {
      try {
        const response = await api.get('/tickets/');
        console.log('API Response:', response.data);

        const myTickets = response.data.filter(
          (ticket) => ticket.creator?.id?.toString() === user.id?.toString()
        );

        setTickets(myTickets);
      } catch (err) {
        console.error('Fetch error:', err);
        const message = err.response?.status === 401 
          ? 'Session expired. Please log in again.'
          : 'Failed to load tickets. Please try again.';
        setError(message);
      } finally {
        setLoading(false);
      }
    };

    fetchTickets();
  }, [token, user]);

  // Match API's uppercase statuses exactly
  const statusCounts = {
    OPEN: tickets.filter(t => t.status === 'OPEN').length,
    IN_PROGRESS: tickets.filter(t => t.status === 'IN_PROGRESS').length,
    RESOLVED: tickets.filter(t => t.status === 'RESOLVED').length, // or 'CLOSED' if that's used
  };

  const getPriorityColor = (priority) => {
    const p = priority?.toUpperCase() || '';
    if (p.includes('HIGH')) return '#ff4d4f';
    if (p === 'MEDIUM') return '#faad14';
    if (p === 'LOW') return '#52c41a';
    return '#d9d9d9';
  };

  const getStatusColor = (status) => {
    switch (status?.toUpperCase()) {
      case 'OPEN': return '#1890ff'; // Blue
      case 'IN_PROGRESS': return '#faad14'; // Orange
      case 'RESOLVED': return '#52c41a'; // Green
      default: return '#d9d9d9';
    }
  };

  if (loading) {
    return <div style={styles.loading}>Loading your tickets...</div>;
  }

  if (error) {
    return <div style={styles.error}>{error}</div>;
  }

  return (
    <div style={styles.container}>
      <h2 style={styles.title}>My IT Support Tickets</h2>

      {/* Counts - Now match API casing */}
      <div style={styles.countsGrid}>
        <div style={{ ...styles.countCard, borderColor: '#1890ff', background: '#e6f7ff' }}>
          <h3 style={styles.countNumber}>{statusCounts.OPEN}</h3>
          <p style={styles.countLabel}>Open</p>
        </div>
        <div style={{ ...styles.countCard, borderColor: '#faad14', background: '#fffbe6' }}>
          <h3 style={styles.countNumber}>{statusCounts.IN_PROGRESS}</h3>
          <p style={styles.countLabel}>In Progress</p>
        </div>
        <div style={{ ...styles.countCard, borderColor: '#52c41a', background: '#f6ffed' }}>
          <h3 style={styles.countNumber}>{statusCounts.RESOLVED}</h3>
          <p style={styles.countLabel}>Resolved</p>
        </div>
      </div>

      {/* Tickets */}
      {tickets.length === 0 ? (
        <div style={styles.noTickets}>
          <p>You haven't created any tickets yet.</p>
          <p style={{ marginTop: '8px' }}>
            <Link to="/create-ticket" style={{ color: '#1890ff' }}>Create New Ticket</Link>
          </p>
        </div>
      ) : (
        <div style={styles.ticketsGrid}>
          {tickets.map((ticket) => (
            <Link to={`/tickets/${ticket.id}`} key={ticket.id} style={styles.ticketLink}>
              <div style={styles.ticketCard}>
                <div style={styles.ticketHeader}>
                  <h4 style={styles.ticketTitle}>#{ticket.id} - {ticket.title}</h4>
                  <span style={{ ...styles.badge, background: getPriorityColor(ticket.priority) }}>
                    {ticket.priority}
                  </span>
                  <span style={{ ...styles.badge, background: getStatusColor(ticket.status) }}>
                    {ticket.status}
                  </span>
                </div>
                <p style={styles.ticketDescription}>{ticket.description?.substring(0, 150)}...</p>
                <p style={styles.ticketMeta}>
                  Created: {new Date(ticket.created_at).toLocaleDateString()}
                </p>
              </div>
            </Link>
          ))}
        </div>
      )}
    </div>
  );
};

// Styles (improved contrast for counts - bolder borders, darker text)
const styles = {
  container: { padding: '32px', maxWidth: '1200px', margin: '0 auto', background: '#f8f9fa', minHeight: '100vh' },
  title: { fontSize: '28px', marginBottom: '32px', color: '#1a1a1a', fontWeight: '600' },
  countsGrid: { display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(220px, 1fr))', gap: '20px', marginBottom: '40px' },
  countCard: { 
    padding: '24px', 
    borderRadius: '12px', 
    border: '3px solid', // Bolder border for better visibility
    textAlign: 'center', 
    boxShadow: '0 6px 16px rgba(0,0,0,0.1)',
    transition: 'transform 0.2s',
  },
  countNumber: { fontSize: '42px', margin: '0 0 12px', fontWeight: 'bold', color: '#1a1a1a' }, // Darker text
  countLabel: { fontSize: '18px', color: '#333', margin: 0, fontWeight: '500' },
  // ... (rest of your styles remain the same)
};

export default EmployeeDashboard;
